<template><ForgeDialog title="HTTP status codes" description="Search standard response codes by number, name or meaning." eyebrow="WORKSPACE / NETWORK" wide @close="emit('close')"><div class="status-panel"><input v-model="query" autofocus placeholder="Search 404, not found, redirect…" /><div class="status-list"><article v-for="item in filtered" :key="item.code"><b>{{ item.code }}</b><span><strong>{{ item.name }}</strong><small>{{ item.description }}</small></span></article><p v-if="!filtered.length" class="empty-copy">No status codes match.</p></div></div></ForgeDialog></template>
<script setup lang="ts">
import { computed, ref } from 'vue'
import ForgeDialog from './ForgeDialog.vue'
const emit=defineEmits<{close:[]}>(); const query=ref(''); const codes=[{code:100,name:'Continue',description:'The request headers have been received.'},{code:200,name:'OK',description:'The request succeeded.'},{code:201,name:'Created',description:'A resource was created.'},{code:204,name:'No Content',description:'The request succeeded without a response body.'},{code:301,name:'Moved Permanently',description:'The resource has a new permanent URL.'},{code:302,name:'Found',description:'The resource is temporarily available elsewhere.'},{code:304,name:'Not Modified',description:'Use the cached representation.'},{code:400,name:'Bad Request',description:'The server could not process the request.'},{code:401,name:'Unauthorized',description:'Authentication is required.'},{code:403,name:'Forbidden',description:'The server refuses the request.'},{code:404,name:'Not Found',description:'The requested resource does not exist.'},{code:409,name:'Conflict',description:'The request conflicts with current resource state.'},{code:422,name:'Unprocessable Content',description:'The input is valid syntax but cannot be processed.'},{code:429,name:'Too Many Requests',description:'Rate limit exceeded.'},{code:500,name:'Internal Server Error',description:'Unexpected server failure.'},{code:502,name:'Bad Gateway',description:'Invalid response from an upstream server.'},{code:503,name:'Service Unavailable',description:'The server is temporarily unavailable.'}]; const filtered=computed(()=>codes.filter(i=>(i.code+' '+i.name+' '+i.description).toLowerCase().includes(query.value.toLowerCase())))
</script>
<style scoped>.status-panel{display:grid;gap:12px}.status-panel>input{padding:10px;color:var(--pqt-text);background:var(--pqt-canvas);border:1px solid var(--pqt-border-strong);border-radius:7px;font:12px var(--pqt-font-mono)}.status-list{display:grid;gap:6px;max-height:430px;overflow:auto}.status-list article{display:grid;grid-template-columns:54px 1fr;gap:12px;padding:10px;border:1px solid var(--pqt-border);border-radius:7px}.status-list article>b{color:var(--pqt-accent);font:16px var(--pqt-font-mono)}.status-list span{display:grid;gap:4px}.status-list small{color:var(--pqt-text-muted)}</style>
